package cn.haiduo;

import java.util.*;
import java.math.BigDecimal;
import java.security.Principal;
import jakarta.servlet.http.HttpSession;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.http.HttpStatus;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import cn.haiduo.audit.Audit;

@RestController @RequestMapping("/api/business-edits")
public class BusinessEdits {
 private final JdbcTemplate db;private final OperationsController scope;
 public BusinessEdits(JdbcTemplate db,OperationsController scope){this.db=db;this.scope=scope;}
 record Line(UUID skuId,int quantity){}
 record Edit(String kind,UUID targetId,long version,String name,String code,Boolean archived,Integer quantity,Integer counted,UUID warehouseId,String reason,UUID requestKey,String carrier,String trackingNumber,List<Line> lines,Integer expectedOnHand,Integer expectedReserved){}
 @GetMapping("/{sku}") Object product(@PathVariable UUID sku,Principal p,HttpSession s){UUID t=scope.tenant(p,s);var result=db.queryForList("select k.id,k.code,k.name,k.version,k.product_id,p.name as product_name,coalesce(c.archived,false) as archived,coalesce(c.version,0) as product_version from sku k join product p on p.tenant_id=k.tenant_id and p.id=k.product_id left join product_control c on c.tenant_id=p.tenant_id and c.product_id=p.id where k.tenant_id=? and k.id=?",t,sku);if(result.isEmpty())BusinessWorkflows.fail(HttpStatus.NOT_FOUND,"商品不存在");return result.getFirst();}
 @GetMapping("/history/{target}") Object history(@PathVariable String target,Principal p,HttpSession s){return db.queryForList("select kind,before_state,after_state,actor,reason,created_at from business_history where tenant_id=? and target_id=? order by created_at desc limit 200",scope.tenant(p,s),target);}
 @GetMapping("/order-lines/{id}") Object lines(@PathVariable UUID id,Principal p,HttpSession s){UUID t=scope.tenant(p,s);return db.queryForList("select i.sku_id,k.code,i.quantity,i.unit_cost_cny::text as unit_cost_cny from order_item i join sku k on k.tenant_id=i.tenant_id and k.id=i.sku_id where i.tenant_id=? and i.order_id=?",t,id);}
 @PostMapping @Transactional Object save(@RequestBody Edit r,Principal p,HttpSession s){
  if(r.kind()==null||!Set.of("PRODUCT_EDIT","PRODUCT_ARCHIVE","SKU_CODE","STOCK_COUNT","RECEIPT_PARTIAL","RETURN_RECEIVE","SHIPMENT_EDIT","ORDER_EDIT","ORDER_COPY","PRODUCT_IMAGE").contains(r.kind()))BusinessWorkflows.fail(HttpStatus.BAD_REQUEST,"不支持的编辑操作");
  UUID t=scope.tenant(p,s);BusinessWorkflows.lock(db,t);BusinessWorkflows.authorize(db,t,p.getName(),r.kind());
  if(r.targetId()==null||r.requestKey()==null||r.reason()==null||r.reason().isBlank()||r.reason().length()>500)BusinessWorkflows.fail(HttpStatus.BAD_REQUEST,"请填写对象、原因和请求键");
  var previous=db.queryForList("select kind,target_id,after_state,actor from business_history where tenant_id=? and id=?",t,r.requestKey());
  if(!previous.isEmpty()){var old=previous.getFirst();if(!old.get("actor").equals(p.getName())||!old.get("kind").equals(r.kind())||!old.get("target_id").equals(r.targetId().toString())||!old.get("after_state").equals(BusinessWorkflows.json(r)))BusinessWorkflows.fail(HttpStatus.CONFLICT,"请求键已用于其他修改");return Map.of("status","APPLIED");}
  if(r.kind().equals("STOCK_COUNT")&&r.warehouseId()==null)BusinessWorkflows.fail(HttpStatus.BAD_REQUEST,"请选择盘点仓库");String target=r.kind().equals("STOCK_COUNT")?r.targetId()+":"+r.warehouseId():r.targetId().toString();String before=BusinessWorkflows.snapshot(db,t,r.kind(),target);
  Object proposed=BusinessWorkflows.propose(db,t,p.getName(),r.kind(),target,r);if(proposed!=null)return proposed;
  switch(r.kind()){
   case "PRODUCT_EDIT","PRODUCT_ARCHIVE","SKU_CODE"->product(t,r);
   case "STOCK_COUNT"->count(t,r,p.getName());
   case "RECEIPT_PARTIAL"->partial(t,r,p.getName());
   case "RETURN_RECEIVE"->returned(t,r,p.getName());
   case "SHIPMENT_EDIT"->shipment(t,r);
   case "ORDER_EDIT"->order(t,r);
   case "ORDER_COPY"->copy(t,r,p.getName());
   case "PRODUCT_IMAGE"->{if(db.queryForObject("select count(*) from stored_file where tenant_id=? and id=?",Integer.class,t,r.requestKey())!=1)BusinessWorkflows.fail(HttpStatus.NOT_FOUND,"图片不存在");db.update("update product set image_file_id=? where tenant_id=? and id=(select product_id from sku where tenant_id=? and id=?)",r.requestKey(),t,t,r.targetId());}
   default->BusinessWorkflows.fail(HttpStatus.BAD_REQUEST,"不支持的编辑类型");
  }
  db.update("insert into business_history(id,tenant_id,kind,target_id,before_state,after_state,actor,reason) values(?,?,?,?,?,?,?,?)",r.requestKey(),t,r.kind(),r.targetId().toString(),before,BusinessWorkflows.json(r),p.getName(),r.reason().trim());
  new Audit(db).record(t,p.getName(),r.kind(),r.targetId());return Map.of("status","APPLIED");
 }
 private void product(UUID t,Edit r){
  var rows=db.queryForList("select k.*,coalesce(c.version,0) as product_version from sku k left join product_control c on c.tenant_id=k.tenant_id and c.product_id=k.product_id where k.tenant_id=? and k.id=? for update of k",t,r.targetId());if(rows.isEmpty())BusinessWorkflows.fail(HttpStatus.NOT_FOUND,"SKU不存在");var k=rows.getFirst();
  if(((Number)k.get(r.kind().equals("SKU_CODE")?"version":"product_version")).longValue()!=r.version())BusinessWorkflows.fail(HttpStatus.CONFLICT,"商品版本已变化，请刷新");
  if(r.kind().equals("SKU_CODE")){if(r.code()==null||!r.code().matches("[A-Za-z0-9_-]{1,64}"))BusinessWorkflows.fail(HttpStatus.BAD_REQUEST,"编码格式无效");var codes=db.queryForList("select sku_id from sku_alias where tenant_id=? and code=?",t,r.code());if(!codes.isEmpty()&&!codes.getFirst().get("sku_id").equals(r.targetId()))BusinessWorkflows.fail(HttpStatus.CONFLICT,"编码或历史别名已被占用");db.update("insert into sku_alias values(?,?,?) on conflict do nothing",t,k.get("code"),r.targetId());db.update("insert into sku_alias values(?,?,?) on conflict do nothing",t,r.code(),r.targetId());db.update("update sku set code=?,version=version+1 where tenant_id=? and id=?",r.code(),t,r.targetId());}
  else {if(r.kind().equals("PRODUCT_EDIT")){if(r.name()==null||r.name().isBlank()||r.name().length()>200)BusinessWorkflows.fail(HttpStatus.BAD_REQUEST,"商品名称无效");db.update("update product set name=? where tenant_id=? and id=?",r.name().trim(),t,k.get("product_id"));}else if(r.archived()==null)BusinessWorkflows.fail(HttpStatus.BAD_REQUEST,"请选择归档或恢复");db.update("insert into product_control(tenant_id,product_id,archived,version) values(?,?,?,1) on conflict(tenant_id,product_id) do update set archived=case when ? then excluded.archived else product_control.archived end,version=product_control.version+1",t,k.get("product_id"),Boolean.TRUE.equals(r.archived()),r.kind().equals("PRODUCT_ARCHIVE"));}
 }
 private void count(UUID t,Edit r,String actor){if(r.warehouseId()==null||r.counted()==null||r.counted()<0||r.expectedOnHand()==null||r.expectedReserved()==null)BusinessWorkflows.fail(HttpStatus.BAD_REQUEST,"填写实盘数量及当前库存快照");var stock=db.queryForList("select on_hand,reserved from inventory where tenant_id=? and sku_id=? and warehouse_id=? for update",t,r.targetId(),r.warehouseId());if(stock.isEmpty())BusinessWorkflows.fail(HttpStatus.NOT_FOUND,"库存不存在");var a=stock.getFirst();if(!a.get("on_hand").equals(r.expectedOnHand())||!a.get("reserved").equals(r.expectedReserved()))BusinessWorkflows.fail(HttpStatus.CONFLICT,"库存已变化，请重新盘点申请");if(r.counted()<(Integer)a.get("reserved"))BusinessWorkflows.fail(HttpStatus.CONFLICT,"实盘数量不能小于预占数量");int delta=r.counted()-(Integer)a.get("on_hand");db.update("update inventory set on_hand=? where tenant_id=? and sku_id=? and warehouse_id=?",r.counted(),t,r.targetId(),r.warehouseId());adjust(t,r,"STOCK_COUNT",r.targetId(),r.warehouseId(),delta,actor);}
 private void partial(UUID t,Edit r,String actor){quantity(r);var rows=db.queryForList("select * from stock_receipt where tenant_id=? and request_key=? for update",t,r.targetId());if(rows.isEmpty())BusinessWorkflows.fail(HttpStatus.NOT_FOUND,"入库记录不存在");var a=rows.getFirst();int previous=db.queryForObject("select coalesce(sum(quantity),0) from business_adjustment where tenant_id=? and kind='RECEIPT_PARTIAL' and target_id=?",Integer.class,t,r.targetId());if(db.queryForObject("select count(*) from receipt_reversal where tenant_id=? and receipt_key=?",Integer.class,t,r.targetId())>0||r.quantity()>((Number)a.get("quantity")).intValue()-previous)BusinessWorkflows.fail(HttpStatus.CONFLICT,"已冲销或超过剩余可冲销数量");if(db.update("update inventory set on_hand=on_hand-? where tenant_id=? and sku_id=? and warehouse_id=? and on_hand-reserved>=?",r.quantity(),t,a.get("sku_id"),a.get("warehouse_id"),r.quantity())!=1)BusinessWorkflows.fail(HttpStatus.CONFLICT,"可用库存不足");adjust(t,r,"RECEIPT_PARTIAL",(UUID)a.get("sku_id"),(UUID)a.get("warehouse_id"),r.quantity(),actor);}
 private void returned(UUID t,Edit r,String actor){quantity(r);if(r.lines()==null||r.lines().size()!=1)BusinessWorkflows.fail(HttpStatus.BAD_REQUEST,"每次验收一个SKU，可分次验收");UUID sku=r.lines().getFirst().skuId();var rows=db.queryForList("select o.status,o.warehouse_id,i.quantity from sales_order o join order_item i on i.tenant_id=o.tenant_id and i.order_id=o.id where o.tenant_id=? and o.id=? and i.sku_id=? for update of o",t,r.targetId(),sku);if(rows.isEmpty())BusinessWorkflows.fail(HttpStatus.NOT_FOUND,"订单SKU不存在");var a=rows.getFirst();if(!a.get("status").equals("SHIPPED"))BusinessWorkflows.fail(HttpStatus.CONFLICT,"仅已发货订单可验收退货");int previous=db.queryForObject("select coalesce(sum(quantity),0) from business_adjustment where tenant_id=? and target_id=? and sku_id=? and kind='RETURN_RECEIVE'",Integer.class,t,r.targetId(),sku);if(r.quantity()>(Integer)a.get("quantity")-previous)BusinessWorkflows.fail(HttpStatus.CONFLICT,"超过尚未退回数量");if(db.update("update inventory set on_hand=on_hand+? where tenant_id=? and sku_id=? and warehouse_id=? and on_hand<=?",r.quantity(),t,sku,a.get("warehouse_id"),Integer.MAX_VALUE-r.quantity())!=1)BusinessWorkflows.fail(HttpStatus.CONFLICT,"库存上限冲突");adjust(t,r,"RETURN_RECEIVE",sku,(UUID)a.get("warehouse_id"),r.quantity(),actor);}
 private void shipment(UUID t,Edit r){if(r.carrier()==null||r.carrier().isBlank()||r.carrier().length()>100||r.trackingNumber()==null||r.trackingNumber().isBlank()||r.trackingNumber().length()>100)BusinessWorkflows.fail(HttpStatus.BAD_REQUEST,"承运商或运单号无效");if(db.update("update shipment set carrier=?,tracking_number=?,edit_version=edit_version+1 where tenant_id=? and id=? and edit_version=?",r.carrier().trim(),r.trackingNumber().trim(),t,r.targetId(),r.version())!=1)BusinessWorkflows.fail(HttpStatus.CONFLICT,"运单不存在或轨迹版本变化");}
 private void order(UUID t,Edit r){var rows=db.queryForList("select * from sales_order where tenant_id=? and id=? for update",t,r.targetId());if(rows.isEmpty())BusinessWorkflows.fail(HttpStatus.NOT_FOUND,"订单不存在");var a=rows.getFirst();if(!a.get("status").equals("NEW")||Boolean.TRUE.equals(a.get("import_voided"))||((Number)a.get("inventory_revision")).longValue()!=r.version()||db.queryForObject("select count(*) from csv_import_order where tenant_id=? and order_id=?",Integer.class,t,r.targetId())!=1)BusinessWorkflows.fail(HttpStatus.CONFLICT,"仅当前版本、未撤销的NEW CSV订单可编辑");if(r.lines()==null||r.lines().isEmpty()||r.lines().size()>100||r.warehouseId()==null||db.queryForObject("select count(*) from warehouse where tenant_id=? and id=?",Integer.class,t,r.warehouseId())!=1)BusinessWorkflows.fail(HttpStatus.BAD_REQUEST,"请填写仓库与完整SKU明细");Set<UUID> ids=new HashSet<>();Map<UUID,BigDecimal> costs=new HashMap<>();for(var line:r.lines()){if(line.skuId()==null||line.quantity()<1||line.quantity()>1000000||!ids.add(line.skuId()))BusinessWorkflows.fail(HttpStatus.BAD_REQUEST,"SKU重复或数量无效");BusinessWorkflows.active(db,t,line.skuId());var k=db.queryForList("select cost from sku where tenant_id=? and id=?",t,line.skuId());if(k.isEmpty())BusinessWorkflows.fail(HttpStatus.NOT_FOUND,"SKU不存在");var old=db.queryForList("select unit_cost_cny from order_item where tenant_id=? and order_id=? and sku_id=?",t,r.targetId(),line.skuId());costs.put(line.skuId(),old.isEmpty()?(BigDecimal)k.getFirst().get("cost"):(BigDecimal)old.getFirst().get("unit_cost_cny"));}db.update("delete from order_item where tenant_id=? and order_id=?",t,r.targetId());for(var line:r.lines())db.update("insert into order_item(tenant_id,order_id,sku_id,quantity,unit_cost_cny) values(?,?,?,?,?)",t,r.targetId(),line.skuId(),line.quantity(),costs.get(line.skuId()));db.update("update sales_order set warehouse_id=?,inventory_revision=inventory_revision+1 where tenant_id=? and id=?",r.warehouseId(),t,r.targetId());}
 private void copy(UUID t,Edit r,String actor){var rows=db.queryForList("select * from sales_order where tenant_id=? and id=? for update",t,r.targetId());if(rows.isEmpty())BusinessWorkflows.fail(HttpStatus.NOT_FOUND,"订单不存在");var a=rows.getFirst();if(!a.get("status").equals("CANCELLED")||r.code()==null||!r.code().matches("[A-Za-z0-9_-]{1,64}")||db.queryForObject("select count(*) from csv_import_order where tenant_id=? and order_id=?",Integer.class,t,r.targetId())!=1)BusinessWorkflows.fail(HttpStatus.CONFLICT,"仅已取消CSV订单可使用新编号复制");StringBuilder csv=new StringBuilder("store,order_no,sku,quantity,net,currency,rate");for(var item:db.queryForList("select k.code,i.quantity from order_item i join sku k on k.tenant_id=i.tenant_id and k.id=i.sku_id where i.tenant_id=? and i.order_id=? order by k.code",t,r.targetId()))csv.append('\n').append(a.get("store")).append(',').append(r.code()).append(',').append(item.get("code")).append(',').append(item.get("quantity")).append(',').append(a.get("net")).append(',').append(a.get("currency")).append(',').append(a.get("rate"));var result=(Map<?,?>)new cn.haiduo.orders.CsvOrders(db).importOrders(t,(UUID)a.get("warehouse_id"),csv.toString(),actor,r.requestKey(),null);if(((Number)result.get("imported")).intValue()!=1)BusinessWorkflows.fail(HttpStatus.CONFLICT,"新订单号已占用，请更换");}
 private void quantity(Edit r){if(r.quantity()==null||r.quantity()<1||r.quantity()>1000000)BusinessWorkflows.fail(HttpStatus.BAD_REQUEST,"数量范围1至1000000");}
 private void adjust(UUID t,Edit r,String kind,UUID sku,UUID warehouse,int quantity,String actor){db.update("insert into business_adjustment(id,tenant_id,kind,target_id,sku_id,warehouse_id,quantity,reason,actor) values(?,?,?,?,?,?,?,?,?)",r.requestKey(),t,kind,r.targetId(),sku,warehouse,quantity,r.reason(),actor);}
}
